#!/bin/sh
set -eu

script_dir=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
root=${MBX_BLAZE_ROOT:-"$script_dir/../.blaze"}
if [ "${1:-}" = "--github-env" ]; then
	python3 "$script_dir/install-build-tools.py" --lock "$script_dir/build-tools.json" --root "$root" --github-env
	exit
fi
if [ "${MBX_DISABLE:-0}" = "1" ]; then
	if [ "$#" -gt 0 ]; then exec "$@"; fi
	exit 0
fi
python3 "$script_dir/install-build-tools.py" --lock "$script_dir/build-tools.json" --root "$root"
if [ "$#" -gt 0 ]; then
	# Generated by the pinned installer at runtime.
	# shellcheck source=/dev/null
	. "$root/env.sh"
	exec "$@"
fi
